-- Подборка «Мося рекомендует» (сгенерировано). Идемпотентно: on conflict обновляет данные.
-- FORMA LOUNGE — первым в «Вечеринке» (координаты — как у встреч на Ямской, 22, иначе по адресу).
select 'Тюмень','party',null,'FORMA LOUNGE','ул. Ямская, 22',
  coalesce((select latitude from public.events where address ilike '%Ямская%22%' and latitude is not null order by created_at desc limit 1), 57.14590),
  coalesce((select longitude from public.events where address ilike '%Ямская%22%' and longitude is not null order by created_at desc limit 1), 65.55150),
  null,null,'лаундж-бар, вечеринки и покер по четвергам',null,-10
on conflict (city, category, coalesce(training_type, ''), lower(name)) do update set address=excluded.address, latitude=excluded.latitude, longitude=excluded.longitude, note=excluded.note, sort=excluded.sort, updated_at=now();
